INSERT INTO `productos` (`id`, `nombre`, `descripcion`, `marca_producto`, `marca_vehiculo`, `presentacion`, `imagen_url`, `referencia`, `categoria`, `sub_categoria`, `codigo`) VALUES
(1, 'Rótula Superior Mazda BT-50 3.2', 'Rótula de suspensión superior de alta resistencia de la marca GAP, diseñada específicamente para la Pick-Up Mazda BT-50 con motorización 3.2. Desarrollada bajo estrictos estándares de equipo original para garantizar una alineación precisa de las ruedas.', 'GAP', 'MAZDA', 'Superior', '/../img/Productos/suspencion/rotulas/MAZDA/rota superior Mazda BT-50 3.2 _ GAP UC2R-34-540A/sin fondo/img_1.png', 'UC2R-34-540A', 'Rótulas', 'Suspensión', 'ROT-BT50-3.2-SUP'),
(2, 'Rótula de Suspensión Kyota para Mazda CX-7 / CX-9 (2007-2010)', 'Rótula de suspensión marca Kyota aplicable de forma bilateral en camionetas Mazda CX-7 y CX-9 (modelos 2007 a 2010). Este componente optimiza el movimiento del brazo de control.', 'KYOTA', 'MAZDA', 'Bilateral (Derecho / Izquierdo)', '/../img/Productos/suspencion/rotulas/MAZDA/ROTULA DER-IZQ  CX-7_ CX-9_ 2007- 2010 _KYOTA TB11-34-350/sin fondo/img_1.png', 'TB11-34-350', 'Rótulas', 'Suspensión', 'ROT-CX7CX9-KYO'),
(3, 'Rótula de Suspensión \"555\" (Three Five) para Mazda CX-7 / CX-9', 'Rótula japonesa genuina marca 555 (Three Five) de calidad Premium superior para Mazda CX-7 y CX-9 (2007-2010). Ofrece una resistencia inigualable ante la torsión y un sellado avanzado.', 'THREE FIVE(555)', 'MAZDA', 'Bilateral (Derecho / Izquierdo)/..', '/../img/Productos/suspencion/rotulas/MAZDA/ROTULA DER-IZQ MAZDA CX-7_ CX-9_ 2007... 2010_ THREE FIVE(555) SB-1772_ TB11-34-350/sin fondo/img_1.png', 'TB11-34-350', 'Rótulas', 'Suspensión', 'SB-1772'),
(4, 'Rótula Inferior Mazda B2600 (1992-2005)', 'Rótula de suspensión inferior apta para los costados Derecho e Izquierdo de las pick-ups de trabajo pesado Mazda B2600, abarcando modelos desde 1992 hasta 2005.', 'Homologado de Alta Calidad', 'MAZDA', 'Inferior (Bilateral)', '/../img/Productos/suspencion/rotulas/MAZDA/ROTULA INF D-I B2600 92-05/sin fondo/img_1.png', 'B2600-INF-DI', 'Rótulas', 'Suspensión', 'ROT-B2600-INF'),
(5, 'Rótula Inferior GAP para Mazda 2 / Ford Fiesta / Ecosport', 'Rótula inferior marca GAP con una amplia compatibilidad multimarca. Diseñada como la pieza ideal de reemplazo para Mazda 2, Ford Ecosport y Ford Fiesta VI.', 'GAP', 'MAZDA / FORD', 'Inferior (Bilateral)', '/../img/Productos/suspencion/rotulas/MAZDA/ROTULA INFERIOR D-I MAZDA 2 2007-2014_ ROTULA INFERIOR D-I FORD ECOSPORT 2013-2020_ ROTULA INFERIOR D-I FORD FIESTA VI 2008-2016 _ DESF-34-350B GAP/sin fondo/img_1.png', 'DESF-34-350B', 'Rótulas', 'Suspensión', 'ROT-MULTIFORD-GAP'),
(6, 'Rótula Inferior TNK para Mazda 2 / Ford Fiesta / Ecosport', 'Rótula inferior de la prestigiosa marca TNK, referencia MZA802. Compatible con plataformas compartidas de Mazda 2, Ford Ecosport y Ford Fiesta VI.', 'TNK', 'MAZDA / FORD', 'Inferior (Bilateral)', '/../img/Productos/suspencion/rotulas/MAZDA/ROTULA INFERIOR D-I MAZDA 2 2007-2014_ ROTULA INFERIOR D-I FORD ECOSPORT 2013-2020_ ROTULA INFERIOR D-I FORD FIESTA VI 2008-2016 _ TNK MZA802/sin fondo/img_1.png', 'MZA802', 'Rótulas', 'Suspensión', 'ROT-MZA802-TNK'),
(7, 'Rótula Inferior Mazda B2000 / B2200', 'Rótula de suspensión inferior marca GAP diseñada para las camionetas clásicas Mazda B2000 y B2200. Sigue estrictamente los parámetros de fábrica.', 'GAP', 'MAZDA', 'Inferior', '/../img/Productos/suspencion/rotulas/MAZDA/ROTULA INFERIOR MAZDA B2000_ B2200 _ GAP, UB39-99-356/sin fondo/img_1.png', 'UB39-99-356', 'Rótulas', 'Suspensión', 'ROT-B2000-INF'),
(8, 'Rótula Inferior Mazda BT-50 4x2', 'Rótula de suspensión inferior de alta ingeniería para pick-ups Mazda BT-50 con tracción sencilla (4x2). Diseñada para acoplarse eficientemente a la geometría trasera.', 'Homologado de Alta Calidad', 'MAZDA', 'Inferior', '/../img/Productos/suspencion/rotulas/MAZDA/ROTULA INFERIOR MAZDA BT-50 4X2_ UR58-64-/sin fondo/img_1.png', 'UR58-64-', 'Rótulas', 'Suspensión', 'ROT-BT50-4X2-INF'),
(9, 'Rótula Inferior GAP para Mazda BT-50 4x4', 'Rótula inferior marca GAP reforzada para camionetas Mazda BT-50 con tracción integral (4x4). Diseñada para tolerar los rigores extremos del Off-Road.', 'GAP', 'MAZDA', 'Inferior', '/../img/Productos/suspencion/rotulas/MAZDA/rotula inferior mazda bt-50 4x4 _ GAP/sin fondo/img_1.png', 'BT50-4X4-INF-GAP', 'Rótulas', 'Suspensión', 'ROT-BT50-4X4-GAP'),
(10, 'Rótula Inferior Delantera Mazda BT-50 4x4', 'Rótula inferior delantera diseñada para restaurar el ensamble crítico del tren motriz 4x4 de la Mazda BT-50. Cuenta con materiales tratados térmicamente.', 'Homologado Premium', 'MAZDA', 'Inferior Delantera', '/../img/Productos/suspencion/rotulas/MAZDA/Rotula Inferior Mazda BT-50 4x4 Delantera/sin fondo/img_1.png', 'BT50-4X4-INF-DEL', 'Rótulas', 'Suspensión', 'ROT-BT50-4X4-DEL'),
(11, 'Rótula Inferior Tecnogama para Mazda BT-50 / Ford Ranger', 'Rótula inferior de la marca nacional Tecnogama, apta para plataformas hermanas Mazda BT-50 y Ford Ranger. Su manufactura robusta previene fallas por sobrepeso.', 'Tecnogama', 'MAZDA / FORD', 'Inferior', '/../img/Productos/suspencion/rotulas/MAZDA/rotula inferior mazda bt-50_ Ford Ranger _ Tecnogama/sin fondo/img_1.png', 'BT50-RANGER-INF', 'Rótulas', 'Suspensión', 'ROT-BT50-TG'),
(12, 'Rótula Inferior Tecnogama para Mazda 323 (RYL 1983-1992)', 'Rótula inferior marca Tecnogama fabricada con especificaciones técnicas precisas para el icónico Mazda 323 (línea clásica RYL de los años 1983 a 1992).', 'TecnoGama', 'MAZDA', 'Inferior', '/../img/Productos/suspencion/rotulas/MAZDA/Rotula Inferior RYL 323 83 ... 92 _TecnoGama/sin fondo/img_1.png', 'M323-8392-TG', 'Rótulas', 'Suspensión', 'ROT-323-CLASSIC'),
(13, 'Rótula Inferior TNK para Mazda 323 (RYL 1983-1992)', 'Rótula de suspensión inferior marca TNK orientada a vehículos Mazda 323 línea RYL (1983-1992). Su guardapolvo de caucho cloropreno sella herméticamente la grasa.', 'TNK', 'MAZDA', 'Inferior', '/../img/Productos/suspencion/rotulas/MAZDA/rotula inferior RYL 323 83... 92 _ TNK/sin fondo/img_1.png', 'M323-8392-TNK', 'Rótulas', 'Suspensión', 'ROT-323-TNK'),
(14, 'Rótula Inferior TNK para Mazda BT-50 2.5 L 4x4', 'Rótula de suspensión inferior desarrollada por TNK para la Mazda BT-50 motorización 2.5 Litros con tracción 4x4. Proporciona una rigidez de pivote exacta.', 'TNK', 'MAZDA', 'Inferior', '/../img/Productos/suspencion/rotulas/MAZDA/Rotula inferior RYL BT-50 2.5 L4x4 _ TNK/sin fondo/img_1.png', 'BT50-2.5-4X4', 'Rótulas', 'Suspensión', 'ROT-BT50-25-TNK'),
(15, 'Rótula de Suspensión GAP para Mazda 3 Skyactive (2015)', 'Rótula de suspensión de alto desempeño de la marca GAP, diseñada a la medida para la tecnología del Mazda 3 Skyactive (modelo 2015).', 'GAP', 'MAZDA', 'Bilateral (Derecho / Izquierdo)', '/../img/Productos/suspencion/rotulas/MAZDA/rotula mazda 3 Skyactive 2015 _ GAP BK3P-34-300D/sin fondo/img_1.png', 'BK3P-34-300D', 'Rótulas', 'Suspensión', 'ROT-M3SKY-GAP'),
(16, 'Rótula Kyota Multiuso para Mazda 3 / 6 / CX-3 / CX-5 Skyactive', 'Rótula de suspensión marca Kyota con amplio espectro de compatibilidad para la línea moderna Skyactive de Mazda.', 'Kyota', 'MAZDA', 'Bilateral (Derecho / Izquierdo)', '/../img/Productos/suspencion/rotulas/MAZDA/Rotula mazda 3_ 6 cx-3, cx-5 skyactive_ Kyota KD35-34-350/sin fondo/img_1.png', 'KD35-34-350', 'Rótulas', 'Suspensión', 'ROT-SKY-MULTIKYO'),
(17, 'Rótula GAP para Mazda Allegro / Mitsubishi Lancer', 'Rótula de suspensión GAP compatible de manera compartida con el Mazda Allegro y el Mitsubishi Lancer.', 'GAP', 'MAZDA / MITSUBISHI', 'Bilateral (Derecho / Izquierdo)', '/../img/Productos/suspencion/rotulas/MAZDA/ROTULA MAZDA ALLEGRO_ MITSUBISHI LANSER _ GAP B01A-34-550-A/sin fondo/img_1.png', 'B01A-34-550A', 'Rótulas', 'Suspensión', 'ROT-ALLEGRO-GAP'),
(18, 'Rótula de Suspensión GAP para Mazda 323 (Línea RYL)', 'Rótula marca GAP para modelos Mazda 323 clásicos (Línea RYL desde 1983 en adelante). Un componente fiable que cumple con especificaciones OEM de la época.', 'GAP', 'MAZDA', 'Inferior', '/../img/Productos/suspencion/rotulas/MAZDA/rotula RYL 323 83... GAP/sin fondo/img_1.png', 'M323-83-GAP', 'Rótulas', 'Suspensión', 'ROT-323-GAP-RYL'),
(19, 'Rótula Superior GAP para Mazda B2600 / BT-50', 'Rótula superior marca GAP con aplicación dual en camionetas pick-up Mazda B2600 y Mazda BT-50. Diseñada para tolerar altos esfuerzos axiales.', 'GAP', 'MAZDA', 'Superior', '/../img/Productos/suspencion/rotulas/MAZDA/Rotula Superior Mazda B2600, BT-50 _ GAP/sin fondo/img_1.png', 'B2600-BT50-SUP-GAP', 'Rótulas', 'Suspensión', 'ROT-B2600-SUP-GAP'),
(20, 'Rótula Superior Whang yu para Mazda B2600 / BT-50', 'Rótula de suspensión superior marca Whang yu para pick-ups Mazda B2600 y BT-50. Cuenta con un revestimiento especial anticorrosivo.', 'Whang yu', 'MAZDA', 'Superior', '/../img/Productos/suspencion/rotulas/MAZDA/Rotula Superior Mazda B2600, BT-50 _ Whang yu/sin fondo/img_1.png', 'B2600-BT50-SUP-WY', 'Rótulas', 'Suspensión', 'ROT-B2600-SUP-WY'),
(21, 'Rótula Superior Tecnogama para Mazda BT-50 / Ford Ranger', 'Rótula superior marca Tecnogama para plataformas compartidas Mazda BT-50 y Ford Ranger.', 'Tecnogama', 'MAZDA / FORD', 'Superior', '/../img/Productos/suspencion/rotulas/MAZDA/rotula superior mazda BT-50_ FORD RANGER _ Tecnogama UC2R-34-0540A/sin fondo/img_1.png', 'UC2R-34-0540A', 'Rótulas', 'Suspensión', 'ROT-BT50-SUP-TG'),
(22, 'Rotula Inferior Derecha Chevrolet Aveo 2011 / Sail 2013', '\'Esta rótula de suspensión de alta resistencia está diseñada específicamente para cumplir con las exigencias del tren delantero de los vehículos de la línea Chevrolet. Su función principal es actuar como el punto de pivote crítico entre las manguetas de dirección y los brazos de control (tijeras), permitiendo un movimiento suave, articulado y controlado de las ruedas durante la conducción. Al estar ubicada en la posición inferior derecha, este componente soporta directamente una carga estructural masiva y absorbe los impactos severos del terreno, garantizando que la geometría de la suspensión se mantenga firme y alineada para evitar desgastes irregulares en las llantas.<br><br>El componente destaca por su amplia compatibilidad con plataformas de alto tránsito en el país, siendo el reemplazo ideal para el Chevrolet Aveo (modelo 2011) y el Chevrolet Sail (modelos de 2013 en adelante). Fabricada bajo estrictos estándares metalúrgicos por la marca WHANG YU bajo las referencias 95907943 y 95017034, la pieza cuenta con un pasador de bola de acero forjado y tratado térmicamente para prevenir fracturas por fatiga, complementado con un guardapolvo de caucho sintético de alta resistencia que sella herméticamente el interior contra el agua, el polvo y el lodo. Esto asegura una lubricación interna constante y prolonga drásticamente la vida útil del sistema de dirección, devolviéndole al vehículo la firmeza, la seguridad y el confort original de marcha.\',', 'WHANG YU', 'CHEVROLET', 'Inferior Derecho', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA CHEVROLET AVEO 2011_ SAIL 2013- INFERIOR DERECHO_ WHANG YU 95907943 95017034/sin fondo/img_1.png', '95907943 / 95017034', 'Rótulas', 'Suspensión', 'ROT-AVEO11-WY'),
(23, 'ROTULA CHEVROLET CORSA DIESEL', 'Rótula de suspensión delantera de servicio pesado para Chevrolet Corsa Diésel.<br>Fabricada por GAP bajo la referencia 90542574, diseñada para soportar la carga y torque adicional de motores diésel.', 'GAP', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/CHEVROLET CORSA DIESEL _ 90542574 GAP/sin fondo/img_1.png', '90542574', 'Rótulas', 'Suspensión', 'ROT-CORSA-DIESEL-GAP'),
(24, 'ROTULA CHEVROLET LUV 1600_ 2300 _ TROOPER', 'Rótula de suspensión reforzada para modelos utilitarios Chevrolet Luv y Trooper.<br>Desarrollada por GAP bajo referencia 8-94224-550-1, ideal para trabajo pesado en terrenos difíciles.', 'GAP', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/chevrolet luv 1600_ 2300 _ Trooper _ GAP 8-94224-550-1/sin fondo/img_1.png', '8-94224-550-1', 'Rótulas', 'Suspensión', 'ROT-LUV-TROOPER-GAP'),
(25, 'ROTULA SUPERIOR CHEVROLET LUV 2300 1995_ TROPER 2.6LTS SUPERIOR', 'Componente de suspensión superior para Chevrolet Luv 2300 y Trooper 2.6L.<br>Fabricado por VIEMAR bajo la referencia comercial 503307, estabiliza los ángulos de caída del tren delantero.', 'VIEMAR', 'CHEVROLET', 'Superior', '/../img/Productos/suspencion/rotulas/CHEVROLET/CHEVROLET LUV 2300 1995_ TROPER 2.6LTS SUPERIOR_ VIEMAR 503307/sin fondo/img_1.png', '503307', 'Rótulas', 'Suspensión', 'ROT-LUVSUP-VIEMAR'),
(26, 'ROTULA CHEVROLET SPARK M300', 'Rótula de suspensión inferior para la plataforma compacta Chevrolet Spark GT (M300).<br>Identificada con la referencia técnica 95952782P, ofrece un giro suave y elimina holguras en la dirección urbana.', 'GENERICO', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/CHEVROLET SPARK M300 _ 95952782P/sin fondo/img_1.png', '95952782P', 'Rótulas', 'Suspensión', 'ROT-SPARKM300-OE'),
(27, 'ROTULA CHEVROLET CAPTIVA _ SUPER 3 96852964', 'Rótula delantera de alta resistencia diseñada para el sistema de suspensión de Chevrolet Captiva.<br>Producida por la marca SUPER 3 con número de referencia 96852964, asegura un pivotaje estable en todo tipo de terreno.', 'SUPER 3', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA CHEVROLET CAPTIVA _ SUPER 3 96852964/sin fondo/img_1.png', '96852964', 'Rótulas', 'Suspensión', 'ROT-CAPTIVA-S3'),
(28, 'ROTULA CHEVROLET CAPTIVA_ 96852964 GAP', 'Rótula de suspensión delantera con especificaciones de equipo original para Chevrolet Captiva.<br>Marca GAP, referencia de fábrica 96852964. Cuenta con sellado hermético contra partículas abrasivas.', 'GAP', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA CHEVROLET CAPTIVA_ 96852964 GAP/sin fondo/img_1.png', '96852964', 'Rótulas', 'Suspensión', 'ROT-CAPTIVA-GAP'),
(29, 'ROTULA CHEVROLET CORSA 1.4 DIESEL _ TNK CA903', 'Rótula delantera de suspensión para la línea Chevrolet Corsa 1.4 Diésel.<br>Fabricada por TNK bajo el código técnico CA903, mitiga vibraciones y optimiza el confort de marcha.', 'TNK', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA CHEVROLET CORSA 1.4 DIESEL _ TNK CA903/sin fondo/img_1.png', 'CA903', 'Rótulas', 'Suspensión', 'ROT-CORSA14-TNK'),
(30, 'ROTULA CHEVROLET CORSA 95-98 _ 90295324 GAP', 'Rótula de recambio para Chevrolet Corsa modelos de 1995 a 1998.<br>Desarrollada por GAP, referencia 90295324. Incorpora un guardapolvo elastómero de larga duración.', 'GAP', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA CHEVROLET CORSA 95-98 _ 90295324 GAP/sin fondo/img_1.png', '90295324', 'Rótulas', 'Suspensión', 'ROT-CORSA9598-GAP'),
(31, 'ROTULA CHEVROLET LUX 4X4 79-83_ IZUSU PICKUP 4X4 84-87_ IZUSU TROOPER 83-91', 'Rótula reforzada multiaplicación para ejes 4x4 de Chevrolet Lux, Isuzu Pickup e Isuzu Trooper clásicos.<br>Producida por TNK con la referencia CA143, ideal para demandas de tracción extrema.', 'TNK', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA CHEVROLET LUX 4X4 79-83_ IZUSU PICKUP 4X4 84-87_ IZUSU TROOPER 83-91_ TNK CA143/sin fondo/img_1.png', 'CA143', 'Rótulas', 'Suspensión', 'ROT-LUX4X4-TNK'),
(32, 'ROTULA CHEVROLET TRACKER_ SONI_ ONIX', 'Rótula delantera de suspensión para plataformas Chevrolet Tracker, Sonic y Onix.<br>Marca GAP, número de pieza 95907943. Ofrece un ajuste dimensional exacto en la tijera inferior.', 'GAP', 'CHEVROLET', 'Bilateral', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA CHEVROLET TRACKER_ SONI_ ONIX _ 95907943 GAP/sin fondo/img_1.png', '95907943', 'Rótulas', 'Suspensión', 'ROT-TRACKSON-GAP'),
(33, 'ROTULA INFERIOR CHEVROLET 2300 4X2 (555)', 'Rótula de suspensión de posición inferior aplicable a Chevrolet Luv 2300 con tracción 4x2.<br>Suministrada por TECNOGAMA bajo la referencia original 8-94459-464-1, siguiendo especificaciones 555.', 'TECNOGAMA', 'CHEVROLET', 'Inferior', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA INFERIOR CHEVROLET 2300 4X2 (555) _ TECNOGAMA 8-94459-464-1/sin fondo/img_1.png', '8-94459-464-1', 'Rótulas', 'Suspensión', 'ROT-LUV2300-TG'),
(34, 'ROTULA INFERIOR CHEVROLET AVEO 2005-2012_ ROTULA INFERIOR SAIL 2005-2012', 'Rótula inferior delantera compatible con las líneas Chevrolet Aveo y Sail fabricados entre 2005 y 2012.<br>Fabricada por TNK con la referencia TCA017, reduce ruidos mecánicos molestos al girar.', 'TNK', 'CHEVROLET', 'Inferior', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA INFERIOR CHEVROLET AVEO 2005-2012_ ROTULA INFERIOR SAIL 2005-2012 _ TNK TCA017/sin fondo/img_1.png', 'TCA017', 'Rótulas', 'Suspensión', 'ROT-AVEOSAIL-TNK'),
(35, 'ROTULA INFERIOR CHEVROLET LUV 1600 4X2', 'Rótula inferior de alta durabilidad para pick-ups Chevrolet Luv 1600 versión 4x2.<br>Distribución de TECNOGAMA con número de referencia 8942245521. Construida en metal de alta templabilidad.', 'TECNOGAMA', 'CHEVROLET', 'Inferior', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA INFERIOR CHEVROLET LUV 1600 4X2 _ TECNOGAMA 8942245521/sin fondo/img_1.png', '8942245521', 'Rótulas', 'Suspensión', 'ROT-LUV1600-TG'),
(36, 'ROTULA INFERIOR CHEVROLET LUV 1600 4X4', 'Rótula inferior reforzada para el tren delantero de Chevrolet Luv 1600 con doble tracción (4x4).<br>Marca GAP, código técnico 94243-436-0. Ofrece una óptima articulación en terrenos difíciles.', 'GAP', 'CHEVROLET', 'Inferior', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA INFERIOR CHEVROLET LUV 1600 4X4_ GAP 94243-436-0/sin fondo/img_1.png', '94243-436-0', 'Rótulas', 'Suspensión', 'ROT-LUV4X4-GAP'),
(37, 'ROTULA INFERIOR CHEVROLET LUV1600 4X4', 'Rótula inferior para suspensión delantera de Chevrolet Luv 1600 4x4.<br>Producida por WHANG YU con la referencia 8-94243-236-0-, provista de perno esférico templado por inducción.', 'WHANG YU', 'CHEVROLET', 'Inferior', '/../img/Productos/suspencion/rotulas/CHEVROLET/ROTULA INFERIOR CHEVROLET LUV1600 4X4 _ WHANG YU 8-94243-236-0-/sin fondo/img_1.png', '8-94243-236-0-', 'Rótulas', 'Suspensión', 'ROT-LUV4X4-WY'),
